        "question": "Какъв е типичният химичен пример за „Квантово-механични представи за строежа на електронната обвивка“?",
        "answer": "При атом на хрома (Z = 24) и медта (Z = 29) се наблюдава проскок на електрон от 4s в 3d подслоя поради повишената стабилност на наполовина запълнения (3d5) и изцяло запълнения (3d10) подслой: 24Cr: [Ar] 3d5 4s1; 29Cu: [Ar] 3d10 4s1."
