    "originalNoteExcerpt": "Ключови понятия: s-, p-, d- и f-елементи в Периодичната система, атомен и йонен радиус, йонизационна енергия и електронно сродство, електроотрицателност (по Полинг). Обяснява структурата на Периодичната система (периоди, групи, s-, p-, d- и f-блокове) въз основа на запълването на електронните слоеве и подслоеве. Дефинира величините атомен радиус, йонизационна енергия, електронно сродство и електроотрицателност и обяснява периодичното им изменение по периоди и групи. Предсказва валентността, окислително-редукционния характер и свойствата на химичните елементи по електронната им конфигурация.",
