      "overview": "Обяснява структурата на Периодичната система (периоди, групи, s-, p-, d- и f-блокове) въз основа на запълването на електронните слоеве и подслоеве. Дефинира величините атомен радиус, йонизационна енергия, електронно сродство и електроотрицателност и обяснява периодичното им изменение по периоди и групи. Предсказва валентността, окислително-редукционния характер и свойствата на химичните елементи по електронната им конфигурация. Мястото на химичния елемент в Периодичната система се определя от електронната конфигурация на атома му: номерът на периода съвпада с максималното главно квантово число n (броя електронни слоеве), а принадлежността към s-, p-, d- или f-блока зависи от вида на последния запълващ се подслой. По период отляво надясно атомният радиус намалява, а йонизационната енергия, електронното сродство и електроотрицателността нарастват; по главна група отгоре надолу зависимостите са обратни.",
