        "answer": "s-, p-, d- и f-елементи в Периодичната система, атомен и йонен радиус, йонизационна енергия и електронно сродство, електроотрицателност (по Полинг). Мястото на химичния елемент в Периодичната система се определя от електронната конфигурация на атома му: номерът на периода съвпада с максималното главно квантово число n (броя електронни слоеве), а принадлежността към s-, p-, d- или f-блока зависи от вида на последния запълващ се подслой. По период отляво надясно атомният радиус намалява, а йонизационната енергия, електронното сродство и електроотрицателността нарастват; по главна група отгоре надолу зависимостите са обратни."
