    "originalNoteExcerpt": "Ключови понятия: междумолекулни (вандерваалсови) взаимодействия, полярност (диполен момент) и поляризуемост на молекулите, водородна връзка. Обяснява междумолекулните взаимодействия (вандерваалсови сили – ориентационни, индукционни и дисперсионни) въз основа на полярността и поляризуемостта на молекулите. Описва механизма на образуване на междумолекулна и вътрешномолекулна водородна връзка и влиянието й върху температурите на кипене и разтворимостта на веществата. Свързва вида на кристалната решетка (йонна, атомна, молекулна, метална) с физичните свойства на веществата.",
