        "Очаквани резултати по МОН: Описва механизма на електролитна дисоциация, степента на дисоциация (α), дисоциационната константа (Kd) и закона на Оствалд за разреждането. Прилага протолитната теория на Брьонстед и Лоури за киселини и основи, протолизните константи Ka и Kb, йонното произведение на водата (Kw = 10^-14) и водородния показател pH. Изчислява pH на разтвори на силни киселини и основи и обяснява действието и биологичното значение на буферните разтвори.",
