        "answer": "хидролиза на соли и хидролизна константа (Kh), стандартен електроден потенциал (E°) и галваничен елемент, електролиза и електрохимична корозия. Хидролизата на соли е обратимо протолитно взаимодействие на йоните на солта с водата: соли от слаба киселина и силна основа (Na2CO3, CH3COONa) хидролизират с основна реакция (pH > 7); соли от силна киселина и слаба основа (NH4Cl, AlCl3, CuSO4) – с кисела реакция (pH < 7); соли от силна киселина и силна основа (NaCl, K2SO4) не хидролизират (pH = 7). При окислително-редукционните процеси посоката се определя от стандартните електродни потенциали (E°): окислителят с по-висок E° окислява редуктора с по-нисък E°."
