        "Теоретични основи и закономерности: Съединенията на p-елементите проявяват богато разнообразие от киселинно-основни и окислително-редукционни свойства: амфотерните Al2O3, Al(OH)3, PbO и Pb(OH)2 се разтварят в киселини и алкални основи; CO е несолеобразуващ оксид и силен редуктор; NH3 е слаба основа (приема протон до NH4+) и редуктор (при каталитично окисление дава NO); HNO3 и концентрираната H2SO4 са силни окислители чрез N(+5) и S(+6), които окисляват и метали след водорода (Cu, Ag), без да се отделя водород.",
        "Очаквани резултати по МОН: Изразява с химични уравнения амфотерните свойства на Al2O3, Al(OH)3, PbO и Pb(OH)2 (образуване на комплексни хидроксосоли) и свойствата на CO, CO2, H2CO3, карбонати и хидрогенкарбонати. Изразява свойствата на амоняка (NH3), азотните оксиди, разредената и концентрираната азотна киселина (HNO3), нитратите, фосфорните оксиди и ортофосфорната киселина (H3PO4). Изразява свойствата на H2S, SO2, SO3, разредена и концентрирана сярна киселина (H2SO4), халогеноводородите (HF, HCl, HBr, HI) и оксокиселините на хлора.",
        "Конкретен химичен пример и приложение: В реда на оксокиселините на хлора HClO → HClO2 → HClO3 → HClO4 със степен на окисление от +1 до +7 силата на киселината и термичната стабилност растат, а окислителната способност в разтвор намалява; при безкислородните киселини HF → HCl → HBr → HI силата на киселината и редукционната способност растат.",
