    "originalNoteExcerpt": "Ключови понятия: киселинни дъждове (SO2, NOx) и парников ефект (CO2), еутрофикация на водоемите (нитрати и фосфати), физиологично действие на въглероден оксид (CO) и оловни йони (Pb2+). Свързва свойствата на съединенията на p-елементите с приложението им (минерални торове, киселини, строителни материали, дезинфектанти). Анализира токсичното въздействие и екологичните проблеми, причинени от CO, тежки метали (Pb), азотни и серни оксиди (киселинни дъждове и смог), нитрати и фосфати (еутрофикация на водоемите) и парниковия ефект (CO2).",
