    "originalNoteExcerpt": "Ключови понятия: синтез на амоняк (метод на Хабер – Бош), оптимални технологични условия и циркулационна схема. Описва промишления синтез на амоняк по метода на Хабер – Бош (N2 + 3H2 ⇄ 2NH3 + Q) като обратим, екзотермичен, каталитичен процес с намаляване на обема. Обосновава избора на оптимални технологични условия (налягане 20–30 MPa, температура ~450 °C, железен катализатор с промотори и циркулация на нереагиралите газове).",
