        "Очаквани резултати по МОН: Описва амонячно-содовия метод на Солвей за производство на калцинирана сода (Na2CO3) от наситен разтвор на NaCl, амоняк и въглероден диоксид през утаяване на малкоразтворимия NaHCO3 и термичното му разлагане. Обяснява регенерацията на амоняка от NH4Cl с варно мляко като пример за безотпадна циркулационна технология.",
