    "originalNoteExcerpt": "Ключови понятия: безотпадни и малкоотпадни химични технологии, сероочистване и обезвреждане на промишлени емисии. Анализира основните източници на замърсяване на въздуха, водите и почвите при химическите и металургичните производства. Описва методите за пречистване на отпадни газове и води (улавяне на SO2 за производство на сярна киселина или гипс, каталитична неутрализация на NOx) и принципите на „зелената химия“ и безотпадните технологии.",
