    "title": "Алкани и циклоалкани",
    "originalNoteExcerpt": "Ключови понятия: алкани и циклоалкани (sp3 хибридизация), верижно-радикалово заместване (SR) – иницииране, развитие и прекъсване, термичен и каталитичен крекинг на нефт. Наименува по номенклатурата на IUPAC алкани и циклоалкани и съставя техните конституционни изомери. Обяснява механизма на верижно-радикаловото заместване (SR) при халогениране на алкани (иницииране, развитие и прекъсване на веригата) и високата селективност при бромиране (предимно при третичен > вторичен > първичен C-атом).",
