    "originalNoteExcerpt": "Ключови понятия: алкени (sp2 хибридизация, двойна връзка σ + π), електрофилно присъединяване (AE) и правило на Марковников, качествени реакции за двойна връзка (обезцветяване на бромна вода и KMnO4). Наименува по IUPAC алкени и циклоалкени и изобразява техните верижни, позиционни и геометрични (цис-/транс-) изомери. Изразява с уравнения електрофилното присъединяване (AE) на халогени, халогеноводороди и вода към алкени, като прилага правилото на Марковников през по-стабилния карбениев йон, както и окислението и полимеризацията на алкени.",
