        "answer": "алкени (sp2 хибридизация, двойна връзка σ + π), електрофилно присъединяване (AE) и правило на Марковников, качествени реакции за двойна връзка (обезцветяване на бромна вода и KMnO4). Алкените (CnH2n) съдържат една двойна връзка C=C, съставена от една здрава σ-връзка и една по-слаба и лесно поляризуема π-връзка между sp2-хибридни въглеродни атоми. За тях са типични реакциите на електрофилно присъединяване (AE) на H2, X2, HX и H2O, окисление и полимеризация. При присъединяване на полярни молекули (HX, H2O) към несиметрични алкени се спазва правилото на Марковников: водородът се свързва с по-богатия на водород C-атом от двойната връзка, тъй като реакцията минава през по-стабилния карбениев йон."
