        "answer": "ароматна система (бензеново ядро) и електрофилно заместване (SE), нитриране, сулфониране и халогениране на арени, ориентанти от I род (орто-, пара-) и II род (мета-). Арените (бензен C6H6, толуен C6H5-CH3 и хомолози CnH2n-6) притежават стабилна делокализирана ароматна π-система и встъпват предимно в реакции на електрофилно заместване (SE): халогениране (с FeBr3/FeCl3), нитриране (с нитрираща смес HNO3 + H2SO4), сулфониране и алкилиране. Заместителите от I род (-OH, -NH2, -OR, алкилови групи и халогени) насочват втория заместител на орто- и пара-място, а заместителите от II род (-NO2, -SO3H, -CHO, -COOH, -CN) дезактивират ядрото и насочват на мета-място."
