    "originalNoteExcerpt": "Ключови понятия: карбонилна група (алдехидна и кетонна), нуклеофилно присъединяване (AN) към карбонилна група, качествени реакции за алдехиди (реакция на сребърното огледало и с Cu(OH)2). Класифицира и наименува по IUPAC мастни и ароматни алдехиди и кетони и ги разграничава като функционални изомери. Изразява с химични уравнения нуклеофилното присъединяване към карбонилната група (HCN, NaHSO3), редукцията до първични или вторични алкохоли и окислението на алдехидите („сребърно огледало“ с реактив на Толенс и червена утайка от Cu2O с фелингов реактив или Cu(OH)2).",
