      "overview": "Класифицира и наименува по IUPAC мастни и ароматни алдехиди и кетони и ги разграничава като функционални изомери. Изразява с химични уравнения нуклеофилното присъединяване към карбонилната група (HCN, NaHSO3), редукцията до първични или вторични алкохоли и окислението на алдехидите („сребърно огледало“ с реактив на Толенс и червена утайка от Cu2O с фелингов реактив или Cu(OH)2). Алдехидите (-CHO) и кетоните (>C=O) съдържат силно полярна двойна карбонилна връзка C=O (sp2-хибридизация) и са функционални изомери помежду си. Те участват в нуклеофилно присъединяване (AN) на HCN, NaHSO3, алкохоли и Grignard реактиви, както и в каталитична редукция с H2 (алдехидите до първични алкохоли, кетоните до вторични алкохоли). За разлика от кетоните, алдехидите се окисляват лесно до карбоксилни киселини и дават положителна реакция на „сребърното огледало“ с амонячен разтвор на Ag2O (реактив на Толенс) и червена утайка от Cu2O при нагряване с прясно утаен Cu(OH)2.",
