        "answer": "комплексообразувател, лиганд и координационно число, вътрешна и външна координационна сфера и стабилитетна константа. Координационните (комплексните) съединения съдържат комплексообразувател (обикновено катион на d-елемент със свободни орбитали: Cu2+, Ag+, Zn2+, Fe2+, Fe3+, Al3+), обкръжен от лиганди (нейтрални молекули H2O, NH3, CO или аниони CN-, Cl-, OH-, SCN- с неподелена електронна двойка), които образуват вътрешната координационна сфера. Броят на донорните атоми, директно свързани с централния атом, е координационното число (най-често 2, 4 или 6). Устойчивостта на комплексите в разтвор се измерва със стабилитетната константа β (обратна на константата на нетрайност)."
