        "answer": "За бинарен електролит AgCl с Ks = 1,8.10^-10 mol^2/L^2 моларната разтворимост в чиста вода е s = √Ks ≈ 1,34.10^-5 mol/L, но в 0,1 M разтвор на NaCl (общ йон Cl-) разтворимостта му спада хиляди пъти до s ≈ Ks / 0,1 = 1,8.10^-9 mol/L."
