    "originalNoteExcerpt": "Ключови понятия: емисионен и абсорбционен спектър, спектрофотометрия и закон на Беер, инфрачервена (ИЧ) спектроскопия и ивици на поглъщане, ЯМР-спектроскопия и масспектрометрия (MS). Обяснява физичния принцип на атомно-емисионния и атомно-абсорбционния спектрален анализ и молекулната абсорбционна спектрофотометрия във видимата и ултравиолетовата област (закон на Бугер – Ламберт – Беер: A = ε.b.c). Описва принципите на инфрачервената (ИЧ) спектроскопия (колебателни преходи и характеристични ивици на поглъщане на функционалните групи), ядрено-магнитния резонанс (ЯМР) и масспектрометрията (MS).",
